'use strict';

// MODULES //

var logger = require( 'debug' );
var join = require( '@stdlib/array/base/join' );
var hash = require( './hash.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:account' );


// MAIN //

/**
* Records the disposition of an MDAST node.
*
* @private
* @param {Object} state - conversion state
* @param {Object} node - MDAST node
* @param {string} disposition - disposition
* @param {string} classification - source classification
* @param {string} reason - disposition reason
* @param {Array} targets - target semantic/resource IDs
* @returns {Object} accounting record
*/
function account( state, node, disposition, classification, reason, targets ) {
	var record;
	var key;

	// Use the MDAST traversal path as the identity of a source node. A node can participate in several semantic operations, but must have one disposition...
	key = join( state.provenance.path( node ), '.' );
	if ( state.accounted[ key ] ) {
		return state.accounted[ key ];
	}
	// Retain both the human-readable classification and an exact source hash so that consumers can audit how the input was handled without the source AST...
	record = {
		'astPath': state.provenance.path( node ),
		'disposition': disposition,
		'nodeType': node.type,
		'classification': classification,
		'reason': reason,
		'source': state.provenance.source( [ node ] ),
		'targetRefs': targets || [],
		'sourceHash': hash( state.provenance.slice( node ) )
	};
	state.accounted[ key ] = record;
	state.document.accounting.push( record );
	debug( 'Recorded source accounting disposition: path=%s disposition=%s classification=%s targets=%d', key, disposition, classification, record.targetRefs.length );

	return record;
}


// EXPORTS //

module.exports = account;
